def f(g):
    H=len(g);W=len(g[0]);out=[row[:] for row in g]
    seen=set()
    for r in range(H):
        cands=[c for c in range(W) if g[r][c]==3]
        if not cands: continue
        if len(cands)>1:
            s=min(cands)
            # run length from min to max+2
            L=max(cands)-s+1; step=(L-1)//(len(cands)-1)+1
            if (L-1)%step==0:
                for k in range(s,s+(L-1)//step*step,step): out[r][k]=2
            else: continue
        elif len(cands)==1:
            k=cands[0]; out[r][k-1],out[r][k]=2,3
        else: break
    return out
