def solve(g):
    H=len(g);W=len(g[0]);out=[row[:] for row in g]
    bkg=max(set(x for r in g for x in r), key=lambda v: sum(r.count(v) for r in g))
    mc=[v for v in set(x for r in g for x in r) if v not in (bkg,2)]
    for r in range(H):
        cands=[c for c in range(W) if g[r][c]==mc[0]]
        if len(cands)<2: continue
        s=min(cands); e=max(cands)
        for o in range(s,e+1):
            out[r][o]=2 if (o-s)%2 else mc[0]
    return out
